function parse(text) {
  try {
    const value = JSON.parse(text);
    return value.ok;
  } catch (error) {
    console.log("invalid json: " + error.name);
    return null;
  }
}

console.log(parse("{\"ok\": true}"));
console.log(parse("not json"));

